                        if xbA & (pb|used): continue
                        xtpA={(p[0]+t[0],p[1]+t[1]) for p in xtp}
                        if xtpA & pb: continue
                        if xtpA & (used-free): continue
                        rec(pb|xbA,(free-xtpA)|(xtpA-free),used|xtpA,dict(rel,**{X:(t,kX)}))
