    out=[]; dr=tgt[0]-cur[0]; dc=tgt[1]-cur[1]
    out+= [{'action':'DOWN'}]*max(dr,0)+[{'action':'UP'}]*max(-dr,0)+[{'action':'RIGHT'}]*max(dc,0)+[{'action':'LEFT'}]*max(-dc,0)
